import { render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { PlanForRepoLink } from './PlanForRepoLink.js';
import { PlanItemCard } from './PlanItemCard.js';
import type { PlanItem } from './contracts.js';

// W17-24. From a review to its repository's plan is ONE link carrying the id,
// and it is a navigation — nothing is generated by following it.

vi.mock('../../api/useApiQuery.js', () => ({
  useApiMutation: () => ({ mutate: vi.fn(), isPending: false, error: null }),
  queryKeyFor: () => [],
}));

beforeEach(() => {
  vi.stubGlobal('fetch', vi.fn());
});
afterEach(() => vi.unstubAllGlobals());

describe('PlanForRepoLink (W17-24)', () => {
  it('links to the Plans page scoped to the repository, without a router', () => {
    // Rendered with no RouterProvider, as the finding detail panel's own tests
    // render it: the link degrades to a plain anchor with the same href.
    render(<PlanForRepoLink repoId={12} />);
    expect(screen.getByTestId('plan-for-repo-link')).toHaveAttribute('href', '/plans?repos=12');
  });

  it('fetches nothing — following it creates no plan', () => {
    render(<PlanForRepoLink repoId={12} />);
    expect(fetch).not.toHaveBeenCalled();
  });
});

function item(evidence: Record<string, unknown>): PlanItem {
  return {
    id: 3,
    rank: 1,
    catalog_id: 'sev-findings-cluster',
    source: 'finding',
    recommendation: 'Remediate the cluster',
    effort: 'L',
    status: 'proposed',
    evidence,
    verify_criterion: { metricKey: 'FINDINGS', op: 'lte', target: 0, windowDays: 1 },
    verified_at: null,
  };
}

describe('PlanItemCard finding links (W17-24)', () => {
  it('links the finding ids the generator recorded on the item', () => {
    render(<PlanItemCard item={item({ findingIds: [41, 42] })} />);
    expect(screen.getByTestId('plan-item-finding-3-41')).toHaveAttribute(
      'href',
      '/findings?finding=41',
    );
    expect(screen.getByTestId('plan-item-finding-3-42')).toHaveAttribute(
      'href',
      '/findings?finding=42',
    );
  });

  it('draws no finding link for a metric item — the row holds none', () => {
    render(<PlanItemCard item={item({ metricKeys: ['M6'] })} />);
    expect(screen.queryByTestId('plan-item-findings-3')).not.toBeInTheDocument();
  });
});
